  "Il grosso del campo resta coperto dai pivot a piena dimensione ({r} m); sui contorni si aggiungono pivot ridotti fino a {min} m di raggio.": "L'essentiel du champ reste couvert par les pivots à pleine dimension ({r} m) ; sur les contours, on ajoute des pivots réduits jusqu'à {min} m de rayon.",
  "Il rilievo ombreggiato mostra i sensi delle pendenze; le isoipse ravvicinate = terreno più ripido.": "Le relief ombré montre les orientations des pentes ; les courbes de niveau rapprochées = terrain plus raide.",
