  "Indirizzo o coordinate GPS": "Dirección o coordenadas GPS",
  "Individua le zone idonee nell'AREA attiva: diventano CAMPI (poligoni operativi generati dal sistema), annidati sotto l'area e selezionabili singolarmente. Passo facoltativo: puoi comunque lavorare direttamente sull'AREA (inserire pivot, analizzarla, ecc.) senza generare campi.": "Localiza las zonas aptas en el ÁREA activa: se convierten en CAMPOS (polígonos operativos generados por el sistema), anidados bajo el área y seleccionables individualmente. Paso opcional: también puedes trabajar directamente sobre el ÁREA (insertar pivotes, analizarla, etc.) sin generar campos.",
  "Infrastrutture accessorie del progetto (invasi, stazioni di pompaggio, dati elettrici…). In arrivo.": "Infraestructuras accesorias del proyecto (embalses, estaciones de bombeo, datos eléctricos…). Próximamente.",
