  "Nessuna strada. Tracciala sulla mappa o importa un file; gli impianti evitano il footprint reale (spessore) secondo il franco «Da strade».": "Nenhuma estrada. Trace-a no mapa ou importe um ficheiro; as instalações evitam a área real (espessura) de acordo com a margem «De estradas».",
  "Nessuna zona a valle della presa: spostala più in alto.": "Nenhuma zona a jusante da tomada: desloque-a mais para cima.",
