  "Nessun accessorio per ora. Questa sezione verrà popolata prossimamente.": "Niciun accesoriu deocamdată. Această secțiune va fi completată în curând.",
  "Nessun corso d'acqua rilevato: prova ad alzare la sensibilità.": "Niciun curs de apă detectat: încearcă să crești sensibilitatea.",
