  "Nessuna strada. Tracciala sulla mappa o importa un file; gli impianti evitano il footprint reale (spessore) secondo il franco «Da strade».": "Niciun drum. Trasează-l pe hartă sau importă un fișier; instalațiile evită amprenta reală (grosimea) conform distanței «De la drumuri».",
  "Nessuna zona a valle della presa: spostala più in alto.": "Nicio zonă în aval de priză: mut-o mai sus.",
