  "Profilo: clicca i punti sulla mappa per leggere quote e dislivelli. Ripremi l'icona per chiudere.": "Profil: fă clic pe puncte pe hartă pentru a citi altitudini și diferențe de nivel. Apasă din nou pe pictogramă pentru a închide.",
  "Progetto salvato ✓ ({n} campi, {c} canali, {s} strade, {w} invasi, {p} pivot)": "Proiect salvat ✓ ({n} câmpuri, {c} canale, {s} drumuri, {w} lacuri de acumulare, {p} pivoți)",
