  "Salvataggio automatico attivo — le modifiche vengono salvate da sole": "Автоматты сақтау белсенді — өзгерістер өздігінен сақталады",
  "Salvataggio automatico…": "Автоматты сақтау…",
  "Salvataggio non riuscito (riprovo alla prossima modifica)": "Сақтау сәтсіз аяқталды (келесі өзгерісте қайталаймын)",
  "Salvo il progetto…": "Жоба сақталуда…",
  "Seleziona un progetto prima di creare il link.": "Сілтеме жасамас бұрын жобаны таңдаңыз.",
  "Seleziona un'area a sinistra per crearne i campi.": "Алқаптарын жасау үшін сол жақтан аумақты таңдаңыз.",
  "Seleziona · trascina qui gli oggetti per assegnarli": "Таңдаңыз · нысандарды тағайындау үшін осы жерге сүйреңіз",
  "Sensibilità": "Сезімталдық",
  "Senza campo": "Алқапсыз",
  "Serve un progetto selezionato per salvare.": "Сақтау үшін таңдалған жоба қажет.",
