  "Individua le zone idonee nell'AREA attiva: diventano CAMPI (poligoni operativi generati dal sistema), annidati sotto l'area e selezionabili singolarmente. Passo facoltativo: puoi comunque lavorare direttamente sull'AREA (inserire pivot, analizzarla, ecc.) senza generare campi.": "Findet die geeigneten Zonen im aktiven GEBIET: Sie werden zu FELDERN (vom System erzeugte operative Polygone), unter dem Gebiet verschachtelt und einzeln auswählbar. Optionaler Schritt: Du kannst weiterhin direkt am GEBIET arbeiten (Pivots einfügen, analysieren usw.), ohne Felder zu erzeugen.",
