  "Dal tipo di suolo (infiltrazione) e dall'ET₀ di punta stima il raggio massimo del pivot perché l'intensità di pioggia al bordo non superi l'infiltrazione del terreno. Il valore è usato come raggio di default nella pagina Impianti.": "Na podstawie typu gleby (infiltracja) i szczytowego ET₀ szacuje maksymalny promień pivota tak, aby intensywność opadu na brzegu nie przekraczała infiltracji gruntu. Wartość jest używana jako domyślny promień na stronie Instalacje.",
