  "Nessun accessorio per ora. Questa sezione verrà popolata prossimamente.": "Na razie brak akcesoriów. Ta sekcja zostanie wkrótce uzupełniona.",
  "Nessun corso d'acqua rilevato: prova ad alzare la sensibilità.": "Nie wykryto żadnego cieku wodnego: spróbuj zwiększyć czułość.",
  "Nessuna linea trovata nei file (KMZ/KML/GeoJSON).": "Nie znaleziono żadnej linii w plikach (KMZ/KML/GeoJSON).",
  "Nessuna strada. Tracciala sulla mappa o importa un file; gli impianti evitano il footprint reale (spessore) secondo il franco «Da strade».": "Brak dróg. Narysuj ją na mapie lub zaimportuj plik; instalacje omijają rzeczywisty zarys (grubość) zgodnie z odstępem «Od dróg».",
  "Nessuna zona a valle della presa: spostala più in alto.": "Brak strefy poniżej ujęcia: przesuń je wyżej.",
