  "Copia link": "Копирай връзка",
  "Copri di più con pivot più piccoli sui bordi": "Покрий повече с по-малки пивоти по краищата",
  "Corsi d'acqua confermati: {n}. I pivot li eviteranno.": "Потвърдени водни течения: {n}. Пивотите ще ги избягват.",
