  "Eliminare \"{name}\" dal progetto?": "Да се изтрие ли \"{name}\" от проекта?",
  "Eliminare \"{name}\" e i suoi poligoni figli?": "Да се изтрие ли \"{name}\" и дъщерните му полигони?",
  "Eliminare questo link? Chi ce l'ha non potrà più aprirlo.": "Да се изтрие ли тази връзка? Който я има, няма да може повече да я отвори.",
  "Esci dalla modalità disegno": "Излез от режим на чертане",
