  "Nessun accessorio per ora. Questa sezione verrà popolata prossimamente.": "Пока нет дополнений. Этот раздел будет заполнен в ближайшее время.",
  "Nessun corso d'acqua rilevato: prova ad alzare la sensibilità.": "Водотоки не обнаружены: попробуйте повысить чувствительность.",
  "Nessuna linea trovata nei file (KMZ/KML/GeoJSON).": "В файлах не найдено линий (KMZ/KML/GeoJSON).",
  "Nessuna strada. Tracciala sulla mappa o importa un file; gli impianti evitano il footprint reale (spessore) secondo il franco «Da strade».": "Нет дорог. Нарисуйте дорогу на карте или импортируйте файл; установки обходят реальный след (ширину) согласно отступу «От дорог».",
  "Nessuna zona a valle della presa: spostala più in alto.": "Нет зоны ниже водозабора по течению: переместите его выше.",
  "Nome del link (es. Cliente A)": "Название ссылки (напр. Клиент A)",
  "Nome sotto-area": "Название подобласти",
  "Oggetti non assegnati": "Неназначенные объекты",
  "Oggetto assegnato al campo ✓": "Объект назначен полю ✓",
  "Oggetto scollegato dal campo ✓": "Объект отвязан от поля ✓",
  "Ogni link «fotografa» ciò che è visibile ORA (aree/campi e gruppi di pivot con l'occhio acceso). Nascondi/mostra i livelli come vuoi, poi crea il link: puoi farne più d'uno per mostrare a clienti diversi cose diverse.": "Каждая ссылка «фотографирует» то, что видно СЕЙЧАС (области/поля и группы пивотов с включённым глазом). Скрывайте/показывайте слои как хотите, затем создайте ссылку: можно создать несколько, чтобы показывать разным клиентам разное.",
  "Parametri per il dimensionamento idrico dei pivot: Kc di punta della coltura, efficienza dell'impianto e ore di irrigazione al giorno.": "Параметры для водного расчёта пивотов: пиковый Kc культуры, КПД установки и часы полива в день.",
