  "Indirizzo o coordinate GPS": "Adres of GPS-koördinate",
  "Individua le zone idonee nell'AREA attiva: diventano CAMPI (poligoni operativi generati dal sistema), annidati sotto l'area e selezionabili singolarmente. Passo facoltativo: puoi comunque lavorare direttamente sull'AREA (inserire pivot, analizzarla, ecc.) senza generare campi.": "Identifiseer die geskikte sones in die aktiewe AREA: hulle word VELDE (bedryfspoligone deur die stelsel gegenereer), genes onder die area en individueel selekteerbaar. Opsionele stap: jy kan steeds direk op die AREA werk (spilpunte invoeg, dit ontleed, ens.) sonder om velde te genereer.",
  "Informazioni progetto": "Projekinligting",
  "Infrastrutture accessorie del progetto (invasi, stazioni di pompaggio, dati elettrici…). In arrivo.": "Bykomende infrastruktuur van die projek (damme, pompstasies, elektriese data…). Kom binnekort.",
