  "Nessun accessorio per ora. Questa sezione verrà popolata prossimamente.": "Tiada aksesori buat masa ini. Bahagian ini akan diisi tidak lama lagi.",
  "Nessun corso d'acqua rilevato: prova ad alzare la sensibilità.": "Tiada aliran air dikesan: cuba tingkatkan kepekaan.",
  "Nessuna linea trovata nei file (KMZ/KML/GeoJSON).": "Tiada garis ditemui dalam fail (KMZ/KML/GeoJSON).",
  "Nessuna strada. Tracciala sulla mappa o importa un file; gli impianti evitano il footprint reale (spessore) secondo il franco «Da strade».": "Tiada jalan. Lukisnya pada peta atau import fail; sistem mengelakkan jejak sebenar (ketebalan) mengikut jidar «Dari jalan».",
  "Nessuna zona a valle della presa: spostala più in alto.": "Tiada zon di hilir ambilan: alihkannya lebih tinggi.",
  "Nome del link (es. Cliente A)": "Nama pautan (cth. Pelanggan A)",
  "Nome sotto-area": "Nama sub-kawasan",
  "Oggetti non assegnati": "Objek tidak ditugaskan",
  "Oggetto assegnato al campo ✓": "Objek ditugaskan ke ladang ✓",
  "Oggetto scollegato dal campo ✓": "Objek dinyahsambung dari ladang ✓",
  "Ogni link «fotografa» ciò che è visibile ORA (aree/campi e gruppi di pivot con l'occhio acceso). Nascondi/mostra i livelli come vuoi, poi crea il link: puoi farne più d'uno per mostrare a clienti diversi cose diverse.": "Setiap pautan «memotret» apa yang kelihatan SEKARANG (kawasan/ladang dan kumpulan pivot dengan mata dihidupkan). Sembunyi/tunjuk lapisan mengikut kehendak anda, kemudian cipta pautan: anda boleh cipta lebih daripada satu untuk menunjukkan perkara berbeza kepada pelanggan berbeza.",
  "Parametri per il dimensionamento idrico dei pivot: Kc di punta della coltura, efficienza dell'impianto e ore di irrigazione al giorno.": "Parameter untuk penentuan saiz air pivot: Kc puncak tanaman, kecekapan sistem dan jam pengairan sehari.",
  "Pend. ideale (‰)": "Kecerunan ideal (‰)",
  "Pend. max (‰)": "Kecerunan maks (‰)",
