  "Profilo: clicca i punti sulla mappa": "Profil: klik titik pada peta",
  "Profilo: clicca i punti sulla mappa per leggere quote e dislivelli. Ripremi l'icona per chiudere.": "Profil: klik titik pada peta untuk membaca ketinggian dan beza aras. Tekan ikon sekali lagi untuk menutup.",
  "Progetto salvato ✓ ({n} campi, {c} canali, {s} strade, {w} invasi, {p} pivot)": "Projek disimpan ✓ ({n} ladang, {c} terusan, {s} jalan, {w} takungan, {p} pivot)",
  "Proprietà": "Sifat",
