  "Nessun accessorio per ora. Questa sezione verrà popolata prossimamente.": "Chưa có phụ kiện. Mục này sẽ được bổ sung sắp tới.",
  "Nessun corso d'acqua rilevato: prova ad alzare la sensibilità.": "Không phát hiện dòng chảy: hãy thử tăng độ nhạy.",
