  "Nessuna strada. Tracciala sulla mappa o importa un file; gli impianti evitano il footprint reale (spessore) secondo il franco «Da strade».": "Không có đường. Hãy vẽ trên bản đồ hoặc nhập một tệp; các thiết bị tránh vùng chiếm chỗ thực (bề dày) theo khoảng lùi «Từ đường».",
  "Nessuna zona a valle della presa: spostala più in alto.": "Không có vùng hạ lưu điểm lấy nước: hãy dời nó lên cao hơn.",
