  "Profilo: clicca i punti sulla mappa per leggere quote e dislivelli. Ripremi l'icona per chiudere.": "Trắc dọc: nhấp các điểm trên bản đồ để đọc độ cao và chênh cao. Nhấn lại biểu tượng để đóng.",
  "Progetto salvato ✓ ({n} campi, {c} canali, {s} strade, {w} invasi, {p} pivot)": "Đã lưu dự án ✓ ({n} cánh đồng, {c} kênh, {s} đường, {w} hồ chứa, {p} pivot)",
  "Proprietà": "Thuộc tính",
