  "Zona a valle: {a} ha, fino a −{d} m. Clicca nell'area evidenziata.": "Vùng hạ lưu: {a} ha, tới −{d} m. Nhấp vào khu vực được tô sáng.",
  "Zoom · trascina su un campo per assegnarlo": "Thu phóng · kéo vào một cánh đồng để gán",
  "bacini": "lưu vực",
