  "Ogni tubazione parte dal canale ed è perpendicolare ad esso; serve al massimo {n} pivot per linea.": "Mỗi đường ống bắt đầu từ kênh và vuông góc với kênh; phục vụ tối đa {n} pivot mỗi đường.",
